module config/parser

import std/io (println)
import std/fs (writeFile, readFile)
import std/json (encode, decode, jo, ja, kv, js, jnum, getString, getInt, getStringArrayOrEmpty)
import std/result (Ok, Err)
import std/option (Some, None)
import std/string (chars)
import std/list (filter, length)

pure func countDots(s: string) -> int =
  length(filter(\c. c == ".", chars(s)))

export func main() -> () ! {IO, FS} {
  let configData = encode(jo([
    kv("app_name", js("MyApp")),
    kv("version", js("1.0.0")),
    kv("port", jnum(8080.0)),
    kv("features", ja([js("logging"), js("auth"), js("api")]))
  ]));

  writeFile("app_config.json", configData);

  let content = readFile("app_config.json");

  match decode(content) {
    Ok(json) => {
      let app_name = match getString(json, "app_name") {
        Some(s) => s,
        None => "Unknown"
      };

      let version = match getString(json, "version") {
        Some(s) => s,
        None => ""
      };

      let port = match getInt(json, "port") {
        Some(n) => n,
        None => 0
      };

      let features = getStringArrayOrEmpty(json, "features");

      if port < 1024 || port > 65535 then
        println("Validation error: Invalid port")
      else if countDots(version) != 2 then
        println("Validation error: Invalid version format")
      else if length(features) == 0 then
        println("Validation error: Features list is empty")
      else
        println("Loaded ${app_name} v${version} on port ${show(port)} with ${show(length(features))} features")
    },
    Err(e) => println("Parse error: ${e}")
  }
}

