import json
from pathlib import Path


def load_config(path: str = "app_config.json") -> dict:
    with open(path) as f:
        config = json.load(f)

    port = config["port"]
    if not (1024 <= port <= 65535):
        raise ValueError(f"Port {port} is not between 1024 and 65535")

    version = config["version"]
    if version.count(".") != 2:
        raise ValueError(f"Version '{version}' does not match X.Y.Z format")

    features = config["features"]
    if not features:
        raise ValueError("Features list is empty")

    return config


def create_default_config() -> None:
    config = {
        "app_name": "MyApp",
        "version": "1.0.0",
        "port": 8080,
        "features": ["logging", "auth", "api"],
    }
    with open("app_config.json", "w") as f:
        json.dump(config, f)


def main() -> None:
    config_path = Path("app_config.json")
    if not config_path.exists():
        create_default_config()

    config = load_config(str(config_path))
    print(
        f"Loaded {config['app_name']} v{config['version']} "
        f"on port {config['port']} with {len(config['features'])} features"
    )


if __name__ == "__main__":
    main()

