from __future__ import annotations

type BST = tuple[int, BST, BST] | None

Leaf: BST = None


def insert(tree: BST, val: int) -> BST:
    if tree is Leaf:
        return (val, Leaf, Leaf)
    v, left, right = tree
    if val < v:
        return (v, insert(left, val), right)
    elif val > v:
        return (v, left, insert(right, val))
    else:
        return tree


def size(tree: BST) -> int:
    if tree is Leaf:
        return 0
    _, left, right = tree
    return 1 + size(left) + size(right)


def contains(tree: BST, val: int) -> bool:
    if tree is Leaf:
        return False
    v, left, right = tree
    if val < v:
        return contains(left, val)
    elif val > v:
        return contains(right, val)
    else:
        return True


def isBST(tree: BST, lo: int, hi: int) -> bool:
    if tree is Leaf:
        return True
    v, left, right = tree
    if not (lo < v < hi):
        return False
    return isBST(left, lo, v) and isBST(right, v, hi)


def insertPreservesBST(val: int) -> bool:
    t = Leaf
    t = insert(t, 10)
    t = insert(t, 5)
    t = insert(t, 15)
    t = insert(t, val)
    return isBST(t, -999999, 999999)


def insertThenFind(val: int) -> bool:
    t = Leaf
    t = insert(t, 10)
    t = insert(t, 5)
    t = insert(t, 15)
    t = insert(t, val)
    return contains(t, val)


def main() -> None:
    t = insert(insert(insert(Leaf, 5), 3), 7)
    print(size(t))
    print(str(contains(t, 3)).lower())
    print(str(contains(t, 4)).lower())
    print(str(isBST(t, -999999, 999999)).lower())
    print(str(insertPreservesBST(42)).lower())
    print(str(insertThenFind(42)).lower())


if __name__ == "__main__":
    main()

