export func det2(a: int, b: int, c: int, d: int) -> int ! {}
ensures { result == a * d - b * c }
{
  a * d - b * c
}

export func det3(a: int, b: int, c: int, d: int, e: int, f: int, g: int, h: int, i: int) -> int ! {}
ensures { result == a * (e * i - f * h) - b * (d * i - f * g) + c * (d * h - e * g) }
{
  a * det2(e, f, h, i) - b * det2(d, f, g, i) + c * det2(d, e, g, h)
}

export func identityDet() -> bool ! {}
ensures { result == true }
{
  det3(1, 0, 0, 0, 1, 0, 0, 0, 1) == 1
}

export func zeroRowDet(a: int, b: int, c: int, d: int, e: int, f: int) -> bool ! {}
ensures { result == true }
{
  det3(a, b, c, 0, 0, 0, d, e, f) == 0
}

