def det2(a: int, b: int, c: int, d: int) -> int:
    return a * d - b * c


def det3(
    a: int, b: int, c: int,
    d: int, e: int, f: int,
    g: int, h: int, i: int,
) -> int:
    return (
        a * det2(e, f, h, i)
        - b * det2(d, f, g, i)
        + c * det2(d, e, g, h)
    )


def identityDet() -> bool:
    return det3(1, 0, 0, 0, 1, 0, 0, 0, 1) == 1


def zeroRowDet(
    a: int, b: int, c: int,
    d: int, e: int, f: int,
) -> bool:
    return det3(a, b, c, d, e, f, 0, 0, 0) == 0


def main() -> None:
    print(det2(3, 8, 4, 6))
    print(det3(6, 1, 1, 4, -2, 5, 2, 8, 7))
    print(det3(1, 0, 0, 0, 1, 0, 0, 0, 1))
    print("true" if identityDet() else "false")
    print("true" if zeroRowDet(3, 5, 7, 2, 4, 6) else "false")


