module benchmark/solution
import std/io (println)
import std/string (chars, charCode, repeat)

pure func isDigit(c: string) -> bool =
  charCode(c) >= 48 && charCode(c) <= 57

pure func digitValue(c: string) -> int =
  charCode(c) - 48

pure func encodeRun(current: string, count: int, rest: [string]) -> string =
  match rest {
    [] => "${show(count)}${current}",
    c :: tail => if c == current then encodeRun(current, count + 1, tail) else "${show(count)}${current}${encodeRun(c, 1, tail)}"
  }

pure func encodeChars(cs: [string]) -> string =
  match cs {
    [] => "",
    c :: rest => encodeRun(c, 1, rest)
  }

export pure func encode(s: string) -> string =
  encodeChars(chars(s))

pure func parseNumber(acc: int, cs: [string]) -> {count: int, rest: [string]} =
  match cs {
    [] => {count: acc, rest: []},
    c :: rest => if isDigit(c) then parseNumber(acc * 10 + digitValue(c), rest) else {count: acc, rest: cs}
  }

pure func decodeChars(cs: [string]) -> string =
  match cs {
    [] => "",
    _ => {
      let parsed = parseNumber(0, cs);
      match parsed.rest {
        [] => "",
        c :: rest => "${repeat(c, parsed.count)}${decodeChars(rest)}"
      }
    }
  }

export pure func decode(s: string) -> string =
  decodeChars(chars(s))

export pure func roundtrip(s: string) -> bool =
  decode(encode(s)) == s

export pure func singleCharEncode(c: string) -> string =
  encode(c)

export func main() -> () ! {IO} {
  println(encode("aaabbc"));
  println(encode("xyz"));
  println(decode("3a2b1c"));
  println(decode("1x1y1z"));
  println(show(roundtrip("hello")));
  println(singleCharEncode("q"))
}

