def encode(s: str) -> str:
    if not s:
        return ""
    result: list[str] = []
    count = 1
    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            count += 1
        else:
            result.append(f"{count}{s[i - 1]}")
            count = 1
    result.append(f"{count}{s[-1]}")
    return "".join(result)


def decode(s: str) -> str:
    result: list[str] = []
    i = 0
    while i < len(s):
        count_start = i
        while i < len(s) and s[i].isdigit():
            i += 1
        count = int(s[count_start:i])
        result.append(s[i] * count)
        i += 1
    return "".join(result)


def roundtrip(s: str) -> bool:
    return decode(encode(s)) == s


def singleCharEncode(s: str) -> bool:
    return encode(s) == f"1{s}"


if __name__ == "__main__":
    print(encode("aaabbc"))
    print(encode("xyz"))
    print(decode("3a2b1c"))
    print(decode("1x1y1z"))
    print(str(roundtrip("hello")).lower())
    print(str(singleCharEncode("q")).lower())

