module benchmark/solution

import std/string (chars)

pure func repeatSymbol(sym: string, n: int) -> string =
  if n <= 0 then "" else "${sym}${repeatSymbol(sym, n - 1)}"

pure func digitRoman(d: int, one: string, five: string, ten: string) -> string =
  if d <= 0 then ""
  else if d <= 3 then repeatSymbol(one, d)
  else if d == 4 then "${one}${five}"
  else if d <= 8 then "${five}${repeatSymbol(one, d - 5)}"
  else "${one}${ten}"

export pure func toRoman(n: int) -> string {
  let thousands = repeatSymbol("M", n / 1000);
  let hundreds = digitRoman((n % 1000) / 100, "C", "D", "M");
  let tens = digitRoman((n % 100) / 10, "X", "L", "C");
  let ones = digitRoman(n % 10, "I", "V", "X");
  "${thousands}${hundreds}${tens}${ones}"
}

pure func romanValue(c: string) -> int =
  if c == "I" then 1
  else if c == "V" then 5
  else if c == "X" then 10
  else if c == "L" then 50
  else if c == "C" then 100
  else if c == "D" then 500
  else if c == "M" then 1000
  else 0

pure func parseRoman(cs: [string]) -> int =
  match cs {
    [] => 0,
    c :: rest => match rest {
      [] => romanValue(c),
      n :: tail => {
        let v = romanValue(c);
        let nv = romanValue(n);
        if v < nv then (0 - v) + parseRoman(rest) else v + parseRoman(rest)
      }
    }
  }

export pure func fromRoman(s: string) -> int =
  parseRoman(chars(s))

export pure func roundtrip(n: int) -> bool =
  if n >= 1 && n <= 3999 then fromRoman(toRoman(n)) == n else true

export pure func distinctEncoding(a: int, b: int) -> bool =
  if a >= 1 && a <= 3999 && b >= 1 && b <= 3999 && a != b then toRoman(a) != toRoman(b) else true

export func main() -> () ! {IO} {
  println(toRoman(1994));
  println(toRoman(58));
  println(toRoman(3999));
  println(show(fromRoman("MCMXCIV")));
  println(show(fromRoman("LVIII")));
  println(show(roundtrip(2024)));
  println(show(distinctEncoding(4, 6)))
}

