ROMAN_MAP = [
    (1000, "M"),
    (900, "CM"),
    (500, "D"),
    (400, "CD"),
    (100, "C"),
    (90, "XC"),
    (50, "L"),
    (40, "XL"),
    (10, "X"),
    (9, "IX"),
    (5, "V"),
    (4, "IV"),
    (1, "I"),
]

ROMAN_VALUES = {
    "M": 1000, "CM": 900, "D": 500, "CD": 400,
    "C": 100, "XC": 90, "L": 50, "XL": 40,
    "X": 10, "IX": 9, "V": 5, "IV": 4, "I": 1,
}


def toRoman(n: int) -> str:
    result = []
    for value, numeral in ROMAN_MAP:
        while n >= value:
            result.append(numeral)
            n -= value
    return "".join(result)


def fromRoman(s: str) -> int:
    total = 0
    i = 0
    while i < len(s):
        if i + 1 < len(s) and s[i:i+2] in ROMAN_VALUES:
            total += ROMAN_VALUES[s[i:i+2]]
            i += 2
        else:
            total += ROMAN_VALUES[s[i]]
            i += 1
    return total


def roundtrip(n: int) -> bool:
    return fromRoman(toRoman(n)) == n


def distinctEncoding(a: int, b: int) -> bool:
    return a == b or toRoman(a) != toRoman(b)


if __name__ == "__main__":
    print(toRoman(1994))
    print(toRoman(58))
    print(toRoman(3999))
    print(fromRoman("MCMXCIV"))
    print(fromRoman("LVIII"))
    print("true" if roundtrip(2024) else "false")
    print("true" if distinctEncoding(4, 6) else "false")

