module benchmark/solution

type SSet = SNil | SCons(int, SSet)

pure func sLength(s: SSet) -> int =
  match s {
    SNil => 0,
    SCons(_, rest) => 1 + sLength(rest)
  }

pure func isSorted(s: SSet) -> bool =
  match s {
    SNil => true,
    SCons(_, SNil) => true,
    SCons(x, rest) => match rest {
      SCons(y, _) => if x < y then isSorted(rest) else false,
      SNil => true
    }
  }

pure func sMerge(a: SSet, b: SSet) -> SSet =
  match a {
    SNil => b,
    SCons(x, xs) => match b {
      SNil => a,
      SCons(y, ys) =>
        if x < y then SCons(x, sMerge(xs, b))
        else if x > y then SCons(y, sMerge(a, ys))
        else SCons(x, sMerge(xs, ys))
    }
  }

pure func sIntersect(a: SSet, b: SSet) -> SSet =
  match a {
    SNil => SNil,
    SCons(x, xs) => match b {
      SNil => SNil,
      SCons(y, ys) =>
        if x < y then sIntersect(xs, b)
        else if x > y then sIntersect(a, ys)
        else SCons(x, sIntersect(xs, ys))
    }
  }

pure func toStr(s: SSet) -> string =
  match s {
    SNil => "SNil",
    SCons(x, rest) => "SCons(${show(x)}, ${toStr(rest)})"
  }

pure func mergePreservesSorted(a: SSet, b: SSet) -> bool =
  if isSorted(a) && isSorted(b) then isSorted(sMerge(a, b)) else true

pure func inclusionExclusion(a: SSet, b: SSet) -> bool =
  (sLength(sMerge(a, b)) + sLength(sIntersect(a, b))) == (sLength(a) + sLength(b))

export func main() -> () ! {IO} {
  let a = SCons(1, SCons(3, SCons(5, SNil)));
  let b = SCons(2, SCons(3, SCons(4, SNil)));

  let merged = sMerge(a, b);
  let intersected = sIntersect(a, b);

  println(toStr(merged));
  println(toStr(intersected));
  println(show(sLength(merged)));
  println(show(isSorted(merged)));
  println(show(mergePreservesSorted(a, b)));
  println(show(inclusionExclusion(a, b)))
}

