from __future__ import annotations


class SNil:
    pass


class SCons:
    __match_args__ = ("head", "tail")

    def __init__(self, head: int, tail: SNil | SCons) -> None:
        self.head = head
        self.tail = tail


def toStr(s: SNil | SCons) -> str:
    result = "["
    first = True
    cur: SNil | SCons = s
    while isinstance(cur, SCons):
        if not first:
            result += ","
        first = False
        result += str(cur.head)
        cur = cur.tail
    result += "]"
    return result


def sMerge(a: SNil | SCons, b: SNil | SCons) -> SNil | SCons:
    match (a, b):
        case (SNil(), _):
            return b
        case (_, SNil()):
            return a
        case (SCons(h1, t1), SCons(h2, t2)):
            if h1 < h2:
                return SCons(h1, sMerge(t1, b))
            elif h1 > h2:
                return SCons(h2, sMerge(a, t2))
            else:
                return SCons(h1, sMerge(t1, t2))


def sIntersect(a: SNil | SCons, b: SNil | SCons) -> SNil | SCons:
    match (a, b):
        case (SNil(), _) | (_, SNil()):
            return SNil()
        case (SCons(h1, t1), SCons(h2, t2)):
            if h1 < h2:
                return sIntersect(t1, b)
            elif h1 > h2:
                return sIntersect(a, t2)
            else:
                return SCons(h1, sIntersect(t1, t2))


def sLength(s: SNil | SCons) -> int:
    match s:
        case SNil():
            return 0
        case SCons(_, tail):
            return 1 + sLength(tail)


def isSorted(s: SNil | SCons) -> bool:
    match s:
        case SNil():
            return True
        case SCons(_, SNil()):
            return True
        case SCons(h1, SCons(h2, tail)):
            return h1 < h2 and isSorted(SCons(h2, tail))


def mergePreservesSorted(a: SNil | SCons, b: SNil | SCons) -> bool:
    return isSorted(sMerge(a, b))


