import std/math (intToFloat)
import std/list (map, length)

type User = {name: string, age: int, email: string}

pure func userToJson(u: User) -> Json =
  jo([
    kv("name", js(u.name)),
    kv("age", jnum(intToFloat(u.age))),
    kv("email", js(u.email))
  ])

pure func parseRow(line: string) -> [User] {
  let row = trim(line);
  if row == "" then []
  else match split(row, ",") {
    name :: ageText :: email :: [] => {
      let cleanName = trim(name);
      let cleanEmail = trim(email);
      match stringToInt(trim(ageText)) {
        Some(age) =>
          if age > 0 && contains(cleanEmail, "@") then
            [{name: cleanName, age: age, email: cleanEmail}]
          else
            [],
        None => []
      }
    },
    _ => []
  }
}

pure func parseRows(rows: [string]) -> [User] =
  match rows {
    [] => [],
    line :: rest => parseRow(line) ++ parseRows(rest)
  }

pure func parseCsv(content: string) -> [User] =
  match split(trim(content), "\n") {
    [] => [],
    _ :: rows => parseRows(rows)
  }

