from typing import TypeVar, Callable, Annotated
from functools import wraps

F = TypeVar("F", bound=Callable)

type PURE = Callable
type IO = Annotated[Callable, "IO"]
type IOFS = Annotated[Callable, "IO", "FS"]


def has_io_effect(func: F) -> F:
    """Mark a function as having IO effects."""
    @wraps(func)
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    wrapper._effects = {"IO"}
    return wrapper


def has_io_fs_effects(func: F) -> F:
    """Mark a function as having IO and FS effects."""
    @wraps(func)
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    wrapper._effects = {"IO", "FS"}
    return wrapper


def computeSum(a: int, b: int) -> int:
    return a + b


@has_io_effect
def printSum(a: int, b: int) -> None:
    result = a + b
    print(f"Sum: {result}")


