from __future__ import annotations

from dataclasses import dataclass


class Expr:
    pass


@dataclass(frozen=True)
class Num(Expr):
    value: int


@dataclass(frozen=True)
class Add(Expr):
    left: Expr
    right: Expr


@dataclass(frozen=True)
class Mul(Expr):
    left: Expr
    right: Expr


def eval_expr(expr: Expr) -> int:
    match expr:
        case Num(value):
            return value
        case Add(left, right):
            return eval_expr(left) + eval_expr(right)
        case Mul(left, right):
            return eval_expr(left) * eval_expr(right)
    raise TypeError(f"Unsupported expression: {expr!r}")


