func contains(x: int, xs: [int]) -> bool =
  match xs {
    [] => false,
    y :: rest => if x == y then true else contains(x, rest)
  }

func enqueue(x: int, queue: [int]) -> [int] =
  queue ++ [x]

func enqueueAll(xs: [int], queue: [int]) -> [int] =
  match xs {
    [] => queue,
    x :: rest => enqueueAll(rest, enqueue(x, queue))
  }

func neighbors(graph: [(int, [int])], node: int) -> [int] =
  match graph {
    [] => [],
    (n, ns) :: rest => if n == node then ns else neighbors(rest, node)
  }

func bfsLoop(graph: [(int, [int])], queue: [int], visited: [int]) -> [int] =
  match queue {
    [] => visited,
    node :: rest => {
      if contains(node, visited) then bfsLoop(graph, rest, visited)
      else {
        let ns = neighbors(graph, node);
        let newQueue = enqueueAll(ns, rest);
        let newVisited = enqueue(node, visited);
        bfsLoop(graph, newQueue, newVisited)
      }
    }
  }

func bfs(graph: [(int, [int])], start: int) -> [int] =
  bfsLoop(graph, [start], [])

func printNodes(nodes: [int]) -> () ! {IO} =
