def contains(x, lst):
    for item in lst:
        if item == x:
            return True
    return False


def enqueue(x, queue):
    queue.append(x)
    return queue


def bfs(graph, start):
    adj = {}
    for node, neighbors in graph:
        adj[node] = neighbors

    visited = []
    queue = []
    enqueue(start, queue)

    while len(queue) > 0:
        node = queue.pop(0)
        if not contains(node, visited):
            visited.append(node)
            for neighbor in adj.get(node, []):
                if not contains(neighbor, visited):
                    enqueue(neighbor, queue)

    return visited


def main():
    graph = [(1, [2, 3]), (2, [4]), (3, [4, 5]), (4, []), (5, [])]
    for node in bfs(graph, 1):
