def median(xs: list[int]) -> int:
    if not xs:
        return 0
    sorted_xs = sorted(xs)
    n = len(sorted_xs)
    if n % 2 == 1:
        return sorted_xs[n // 2]
    else:
        return sorted_xs[n // 2 - 1]

