from dataclasses import dataclass
from typing import Any


type Expr = Num | Var | Add | Mul | Let


@dataclass(frozen=True)
class Num:
    value: int


@dataclass(frozen=True)
class Var:
    name: str


@dataclass(frozen=True)
class Add:
    left: Expr
    right: Expr


@dataclass(frozen=True)
class Mul:
    left: Expr
    right: Expr


@dataclass(frozen=True)
class Let:
    name: str
    value: Expr
    body: Expr


Env = list[tuple[str, int]]


def lookup(name: str, env: Env) -> int:
    for n, v in env:
        if n == name:
            return v
    raise NameError(f"undefined variable: {name}")


def eval(expr: Expr, env: Env) -> int:
    match expr:
        case Num(value):
            return value
        case Var(name):
            return lookup(name, env)
        case Add(left, right):
            return eval(left, env) + eval(right, env)
        case Mul(left, right):
            return eval(left, env) * eval(right, env)
        case Let(name, value, body):
            v = eval(value, env)
            return eval(body, [(name, v), *env])


