from __future__ import annotations

from dataclasses import dataclass
from functools import wraps
from typing import TypeAlias

# ── Labels ────────────────────────────────────────────────────────────
#
#  <email>     — untrusted raw input
#  <sanitized> — safe-to-forward string
#  In a real language with labelled types these would be tracked by the
#  type-checker.  Here we track them at runtime inside wrapper objects
#  and refuse to let SendAction hold anything but <sanitized>.

_Label: TypeAlias = str
_EMAIL: _Label = "email"
_SANITIZED: _Label = "sanitized"


class LabeledStr:
    __slots__ = ("_value", "_label")

    def __init__(self, value: str, label: _Label) -> None:
        self._value = value
        self._label = label

    @property
    def value(self) -> str:
        return self._value

    @property
    def label(self) -> _Label:
        return self._label

    def __eq__(self, other: object) -> bool:
        if isinstance(other, LabeledStr):
            return self._value == other._value and self._label == other._label
        return NotImplemented

    def __repr__(self) -> str:
        return f"LabeledStr({self._value!r}, <{self._label}>)"


# ── Effects ───────────────────────────────────────────────────────────

def _mark_effect(effect: str):
    def deco(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            return func(*args, **kwargs)

        wrapper._effect = effect
        return wrapper

    return deco


Declassify = _mark_effect("Declassify")


# ── SendAction ────────────────────────────────────────────────────────

@dataclass(frozen=True)
class SendAction:
    """The body field is *provably* <sanitized> because the only
    constructor checks the label at runtime."""

    _body: LabeledStr
    recipient: str

    @property
    def body(self) -> str:
        if self._body.label != _SANITIZED:
            raise TypeError(
                f"SendAction.body must be <sanitized>, got <{self._body.label}>"
            )
        return self._body.value

    @classmethod
    def create(cls, body: LabeledStr, recipient: str) -> SendAction:
        if body.label != _SANITIZED:
            raise TypeError(
                f"SendAction requires <sanitized> body, got <{body.label}>"
            )
        return cls(_body=body, recipient=recipient)


# ── Core ──────────────────────────────────────────────────────────────

@Declassify
def sanitizeBody(email_body: LabeledStr) -> LabeledStr:
    """sanitizeBody : <email> → <sanitized>   (with {Declassify})"""
    assert email_body.label == _EMAIL, (
        f"sanitizeBody expects <email>, got <{email_body.label}>"
    )
    return LabeledStr("[sanitized]", _SANITIZED)


def safeForward(raw_body: str, recipient: str) -> SendAction:
    """safeForward  :  raw (untrusted) body  ×  internal recipient
                       →  SendAction whose body is always \"[sanitized]\".
    """
    if not recipient.endswith("@company.com"):
        raise ValueError("Recipient must be internal (@company.com)")

    untrusted = LabeledStr(raw_body, _EMAIL)
    clean = sanitizeBody(untrusted)  # raw body never reaches SendAction.body directly
    return SendAction.create(body=clean, recipient=recipient)


def main() -> None:
    action = safeForward("phishing <script>alert(1)</script>", "user@company.com")
    print(1 if action.recipient.endswith("@company.com") else 0)


if __name__ == "__main__":
    main()

