def run_length_encode(chars: list[str]) -> list[tuple[int, str]]:
    if not chars:
        return []

    def encode_recursive(lst, current_char, current_count, result):
        if not lst:
            return result + [(current_count, current_char)]
        if lst[0] == current_char:
            return encode_recursive(lst[1:], current_char, current_count + 1, result)
        else:
            return encode_recursive(lst[1:], lst[0], 1, result + [(current_count, current_char)])

    return encode_recursive(chars[1:], chars[0], 1, [])


