      DispenseDone => Err("not_dispensing")
    },
    HasCredit(c) => match event {
      Insert(n) => Ok(HasCredit(c + n)),
      Select(code) => selectInCredit(c, code),
      DispenseDone => Err("not_dispensing")
    },
    Dispensing(ch) => match event {
      Insert(_) => Err("busy"),
      Select(_) => Err("busy"),
      DispenseDone => Ok(Idle)
    }
  }

pure func showState(s: State) -> string =
  match s {
    Idle => "IDLE",
    HasCredit(n) => "CREDIT(${show(n)})",
    Dispensing(ch) => "DISPENSING(${show(ch)})"
  }

func run(state: State, events: [Event]) -> () ! {IO} =
  match events {
    [] => (),
    e :: rest => {
      let res = step(state, e);
      match res {
        Ok(ns) => {
          println("ok: ${showState(ns)}");
          run(ns, rest)
        },
        Err(reason) => {
          println("err: ${reason}");
          run(state, rest)
        }
      }
    }
  }

export func main() -> () ! {IO} {
  let events = [
    Insert(50),
    Select(1),
    Insert(100),
    Select(1),
    Insert(50),
    DispenseDone,
    Select(2),
    Insert(100),
    Select(2),
    DispenseDone
  ];
  run(Idle, events)
}

