    cents: int


@dataclass(frozen=True)
class Select:
    code: int


@dataclass(frozen=True)
class DispenseDone:
    pass


Event = Insert | Select | DispenseDone


@dataclass(frozen=True)
class Ok:
    state: State


@dataclass(frozen=True)
class Err:
    reason: str


Result = Ok | Err


def step(state: State, event: Event) -> Result:
    match (state, event):
        case (Idle(), Insert(cents=n)):
            return Ok(HasCredit(n))
        case (Idle(), Select()):
            return Err("no_credit")
        case (Idle(), DispenseDone()):
            return Err("not_dispensing")
        case (HasCredit(cents=c), Insert(cents=n)):
            return Ok(HasCredit(c + n))
        case (HasCredit(cents=c), Select(code=code)):
            if code not in (1, 2, 3):
                return Err("unknown_item")
            price = PRICES[code]
            if c < price:
                return Err("insufficient_funds")
            return Ok(Dispensing(c - price))
        case (HasCredit(), DispenseDone()):
            return Err("not_dispensing")
        case (Dispensing(), Insert()):
            return Err("busy")
        case (Dispensing(), Select()):
            return Err("busy")
        case (Dispensing(), DispenseDone()):
            return Ok(Idle())


def print_result(result: Result) -> None:
    match result:
        case Ok(state=Idle()):
            print("ok: IDLE")
        case Ok(state=HasCredit(cents=n)):
            print(f"ok: CREDIT({n})")
        case Ok(state=Dispensing(change=ch)):
            print(f"ok: DISPENSING({ch})")
        case Err(reason=reason):
            print(f"err: {reason}")


