from dataclasses import dataclass
from typing import Union


@dataclass
class Const:
    value: int


@dataclass
class Var:
    name: str


@dataclass
class Add:
    left: "Expr"
    right: "Expr"


@dataclass
class Mul:
    left: "Expr"
    right: "Expr"


Expr = Union[Const, Var, Add, Mul]


def diff(expr: Expr, var: str) -> Expr:
    match expr:
        case Const(_):
            return Const(0)
        case Var(name):
            return Const(1) if name == var else Const(0)
        case Add(left, right):
            return Add(diff(left, var), diff(right, var))
        case Mul(left, right):
            return Add(Mul(left, diff(right, var)), Mul(right, diff(left, var)))


def simplify(expr: Expr) -> Expr:
    match expr:
        case Const(_) | Var(_):
            return expr
        case Add(left, right):
            l = simplify(left)
            r = simplify(right)
            match (l, r):
                case (Const(0), _):
                    return r
                case (_, Const(0)):
                    return l
                case _:
                    return Add(l, r)
        case Mul(left, right):
            l = simplify(left)
            r = simplify(right)
            match (l, r):
                case (Const(0), _) | (_, Const(0)):
                    return Const(0)
                case (Const(1), _):
                    return r
                case (_, Const(1)):
                    return l
                case _:
                    return Mul(l, r)


def showExpr(expr: Expr) -> str:
    match expr:
        case Const(value):
            return str(value)
        case Var(name):
            return name
        case Add(left, right):
            return f"({showExpr(left)} + {showExpr(right)})"
        case Mul(left, right):
            return f"({showExpr(left)} * {showExpr(right)})"


def main():
    expr = Add(Add(Mul(Var("x"), Var("x")), Mul(Const(3), Var("x"))), Const(5))
    derivative = diff(expr, "x")
    simplified = simplify(derivative)
    print(showExpr(simplified))


if __name__ == "__main__":
    main()

