from __future__ import annotations

from dataclasses import dataclass
from typing import Callable


@dataclass
class Leaf:
    value: int


@dataclass
class Node:
    left: Leaf | Node
    value: int
    right: Leaf | Node


Tree = Leaf | Node


def mapTree(fn: Callable[[int], int], tree: Tree) -> Tree:
    match tree:
        case Leaf(value=v):
            return Leaf(fn(v))
        case Node(left=l, value=v, right=r):
            return Node(mapTree(fn, l), fn(v), mapTree(fn, r))


def foldTree(fn: Callable[[int, int], int], acc: int, tree: Tree) -> int:
    match tree:
        case Leaf(value=v):
            return fn(acc, v)
        case Node(left=l, value=v, right=r):
            left_result = foldTree(fn, acc, l)
            mid = fn(left_result, v)
            return foldTree(fn, mid, r)


def treeToList(tree: Tree) -> list[int]:
    match tree:
        case Leaf(value=v):
            return [v]
        case Node(left=l, value=v, right=r):
            return treeToList(l) + [v] + treeToList(r)


def treeDepth(tree: Tree) -> int:
    match tree:
        case Leaf():
            return 1
        case Node(left=l, right=r):
            return 1 + max(treeDepth(l), treeDepth(r))


def main() -> None:
    tree = Node(Node(Leaf(1), 2, Leaf(3)), 4, Node(Leaf(5), 6, Leaf(7)))
    double = lambda x: x * 2
    add = lambda a, b: a + b

    print(treeToList(tree))
    print(treeToList(mapTree(double, tree)))
    print(foldTree(add, 0, tree))
    print(treeDepth(tree))


if __name__ == "__main__":
    main()

