  [] => None,
  (name, t) :: rest => if name == v then Some(t) else lookup(v, rest)
}

pure func apply(subst: Subst, t: Type) -> Type = match t {
  TVar(v) => match lookup(v, subst) {
    Some(t2) => t2,
    None => t
  },
  TFunc(a, r) => TFunc(apply(subst, a), apply(subst, r)),
  other => other
}

pure func unify(t1: Type, t2: Type) -> Option[Subst] {
  match (t1, t2) {
    (TInt, TInt) => Some([]),
    (TBool, TBool) => Some([]),
    (TVar(a), t) => Some([(a, t)]),
    (t, TVar(a)) => Some([(a, t)]),
    (TFunc(a1, r1), TFunc(a2, r2)) => {
      let s1 = unify(a1, a2);
      let s2 = unify(r1, r2);
      match (s1, s2) {
        (Some(s1p), Some(s2p)) => Some(s1p ++ s2p),
        (_, _) => None
      }
    },
    (_, _) => None
  }
}

