from dataclasses import dataclass

@dataclass(frozen=True)
class Type:
    pass

@dataclass(frozen=True)
class TVar(Type):
    name: str

@dataclass(frozen=True)
class TInt(Type):
    pass

@dataclass(frozen=True)
class TBool(Type):
    pass

@dataclass(frozen=True)
class TFunc(Type):
    arg: Type
    result: Type

Substitution = list[tuple[str, Type]]


def apply(subst: Substitution, t: Type) -> Type:
    for var_name, replacement in subst:
        t = _apply_one(var_name, replacement, t)
    return t


def _apply_one(var_name: str, replacement: Type, t: Type) -> Type:
    match t:
        case TVar(name) if name == var_name:
            return replacement
        case TFunc(arg, result):
            return TFunc(
                _apply_one(var_name, replacement, arg),
                _apply_one(var_name, replacement, result),
            )
        case _:
            return t


def unify(t1: Type, t2: Type) -> Substitution | None:
    match (t1, t2):
        case (TInt(), TInt()) | (TBool(), TBool()):
            return []
        case (TVar(name), other):
            return [(name, other)]
        case (other, TVar(name)):
            return [(name, other)]
        case (TFunc(a1, r1), TFunc(a2, r2)):
            s1 = unify(a1, a2)
            if s1 is None:
                return None
            s2 = unify(apply(s1, r1), apply(s1, r2))
            if s2 is None:
                return None
            return s1 + s2
        case _:
            return None


def main() -> None:
    t1 = TFunc(TVar("a"), TInt())
    t2 = TFunc(TBool(), TVar("b"))
    subst = unify(t1, t2)
    if subst is not None:
        for name, ty in subst:
            match ty:
                case TBool():
                    print(f"{name} = TBool")
                case TInt():
                    print(f"{name} = TInt")


if __name__ == "__main__":
    main()

